package com.udhaardaar.mvp

import android.graphics.Color
import android.graphics.Typeface
import android.graphics.drawable.GradientDrawable
import android.content.Intent
import android.os.Bundle
import android.view.Gravity
import android.widget.*
import androidx.appcompat.app.AppCompatActivity

/** ArthSaathi V6.2 premium financial-life command centre. */
class V62HomeActivity : AppCompatActivity() {
    private val navy=Color.rgb(16,45,82); private val green=Color.rgb(18,137,91); private val gold=Color.rgb(211,161,37); private val teal=Color.rgb(12,171,158); private val blue=Color.rgb(42,103,221); private val red=Color.rgb(193,67,72); private val bg=Color.rgb(246,249,252); private val muted=Color.rgb(92,108,124); private val border=Color.rgb(220,228,236)
    private val prefs by lazy{getSharedPreferences("udhaardaar_accounts",MODE_PRIVATE)}
    private fun dp(v:Int)=(v*resources.displayMetrics.density).toInt()
    private fun card(fill:Int=Color.WHITE)=GradientDrawable().apply{setColor(fill);cornerRadius=dp(16).toFloat();setStroke(dp(1),border)}
    private fun text(s:String,size:Float,color:Int=navy,bold:Boolean=false)=TextView(this).apply{text=s;textSize=size;setTextColor(color);typeface=Typeface.create("sans-serif",if(bold)Typeface.BOLD else Typeface.NORMAL)}
    private fun lp(t:Int)=LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(t)}
    private fun action(title:String,sub:String,accent:Int,symbol:String,click:()->Unit)=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER;setPadding(dp(6),dp(9),dp(6),dp(8));background=card();setOnClickListener{click()};addView(text(symbol,24f,accent,true));addView(text(title,12f,navy,true),lp(4));addView(text(sub,9f,muted),lp(2))}
    private fun item(w:Int)=LinearLayout.LayoutParams(0,dp(100),w.toFloat()).apply{rightMargin=dp(4)}
    private fun navItem(w:Int)=LinearLayout.LayoutParams(0,dp(56),w.toFloat())
    override fun onCreate(b:Bundle?){super.onCreate(b);render()}
    override fun onResume(){super.onResume();if(!isFinishing)render()}
    private fun openCredit(){startActivity(Intent(this,V62CreditRegistrationActivity::class.java))}
    private fun openServices(mode:String="MENU"){startActivity(Intent(this,ArthSaathiModulesActivity::class.java).putExtra("mode",mode))}
    private fun render(){if(!prefs.getBoolean("logged_in",false)){startActivity(Intent(this,LoginActivity::class.java));finish();return};val r=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(14),dp(10),dp(14),dp(8));setBackgroundColor(bg)};val m=prefs.getString("current_mobile","")?:"";val name=prefs.getString("name_$m","User")?:"User";val h=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(dp(10),dp(8),dp(8),dp(8));background=card()};h.addView(ImageView(this).apply{setImageResource(R.drawable.udhaardaar_logo);scaleType=ImageView.ScaleType.CENTER_INSIDE;contentDescription="ArthSaathi logo"},LinearLayout.LayoutParams(dp(60),dp(60)));val hb=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};hb.addView(text("ArthSaathi",23f,navy,true));hb.addView(text("Navigate Your Financial Journey",11f,teal,true),lp(2));hb.addView(text("Plan • Protect • Grow • Nominate",9f,gold,true),lp(2));hb.addView(text(name,10f,muted,true),lp(2));h.addView(hb,LinearLayout.LayoutParams(0,-2,1f).apply{leftMargin=dp(9)});r.addView(h);r.addView(text("Good to see you, $name",18f,navy,true),lp(10));r.addView(text("Your financial life, organised in one journey.",11f,muted),lp(2));val metrics=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};metrics.addView(metric("TO RECEIVE","₹0",green),LinearLayout.LayoutParams(0,dp(62),1f).apply{rightMargin=dp(4);topMargin=dp(8)});metrics.addView(metric("TO PAY","₹0",red),LinearLayout.LayoutParams(0,dp(62),1f).apply{leftMargin=dp(4);rightMargin=dp(4);topMargin=dp(8)});metrics.addView(metric("ACTIVE","0",blue),LinearLayout.LayoutParams(0,dp(62),1f).apply{leftMargin=dp(4);topMargin=dp(8)});r.addView(metrics);r.addView(text("SMART ACTIONS",11f,muted,true),lp(13));val g1=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};g1.addView(action("Register Credit","Profiles + terms",blue,"＋"){openCredit()},item(1));g1.addView(action("Repayment","Dues + consent",green,"↻"){startActivity(Intent(this,V62RepaymentActivity::class.java))},item(1));g1.addView(action("Asset Vault","Assets + evidence",teal,"◆"){startActivity(Intent(this,V62AssetVaultActivity::class.java))},item(1));r.addView(g1);val g2=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};g2.addView(action("Protect","Insurance + benefits",green,"⌂"){openServices("INSURANCE")},item(1));g2.addView(action("Legacy","Will + nomination",gold,"◇"){openServices("WILL")},item(1));g2.addView(action("Legal","Claims + lawyers",red,"⚖"){openServices("LEGAL")},item(1));r.addView(g2);val ai=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(dp(12),dp(9),dp(12),dp(9));background=card(Color.rgb(239,249,246));setOnClickListener{openServices("AI")}};ai.addView(text("✦",23f,gold,true),LinearLayout.LayoutParams(dp(34),-2));val ab=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};ab.addView(text("AI Financial Advisor",13f,navy,true));ab.addView(text("Explainable alerts • opportunities • reminders",10f,muted),lp(2));ai.addView(ab,LinearLayout.LayoutParams(0,-2,1f));ai.addView(text("›",24f,teal,true));r.addView(ai,lp(8));val nav=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER;setPadding(dp(4),dp(5),dp(4),dp(4));background=card()};nav.addView(bottom("⌂","Home",true){render()},navItem(1));nav.addView(bottom("₹","Credit",false){openCredit()},navItem(1));nav.addView(bottom("↻","Repay",false){startActivity(Intent(this,V62RepaymentActivity::class.java))},navItem(1));nav.addView(bottom("◆","Vault",false){startActivity(Intent(this,V62AssetVaultActivity::class.java))},navItem(1));nav.addView(bottom("☰","More",false){openServices("MENU")},navItem(1));r.addView(nav,lp(8));setContentView(r)}
    private fun metric(l:String,v:String,c:Int)=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER;background=card();addView(text(l,9f,c,true));addView(text(v,17f,navy,true),lp(3))}
    private fun bottom(s:String,l:String,sel:Boolean,click:()->Unit)=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER;setOnClickListener{click()};addView(text(s,20f,if(sel)teal else muted,true));addView(text(l,9f,if(sel)teal else muted,sel),lp(2))}
}
